// Sky/sea shader adapted from Saltline (saltline.games), used with the project owner's approval.
//
// Deterministic noise textures shared by the sky dome and the sea shader:
//   - tNoise: 256² RGBA white noise, sampled by the sky's value-noise fbm.
//   - detail/detailN: 256² tiles generated by the same `Cb` routine Saltline
//     uses — `detail` packs four decorrelated fbm channels (height, low-freq,
//     warped ridged, mid), `detailN` stores central-difference slopes of two
//     height fields in .rg and .ba for cheap water normals.
// Everything is generated once into a Uint8Array + DataTexture (no external
// assets, no per-frame work).

import * as THREE from 'three';

const SIZE = 256;
const sat = (x: number): number => (x < 0 ? 0 : x > 1 ? 1 : x);

/** Saltline F1 — integer lattice hash → [0,1). */
function F1(i: number, e: number, t: number): number {
  let n =
    Math.imul(i | 0, 374761393) ^ Math.imul(e | 0, 668265263) ^ Math.imul(t | 0, 1274126177);
  n = Math.imul(n ^ (n >>> 13), 1274126177);
  return ((n ^ (n >>> 16)) >>> 0) / 4294967296;
}

/** Saltline Ab — smooth value noise; n = optional tile period for seamless wrap. */
function Ab(i: number, e: number, t: number, n: number): number {
  const s = Math.floor(i);
  const o = Math.floor(e);
  const r = i - s;
  const a = e - o;
  const l = r * r * (3 - 2 * r);
  const c = a * a * (3 - 2 * a);
  let u = s,
    h = s + 1,
    f = o,
    p = o + 1;
  if (n) {
    u = ((u % n) + n) % n;
    h = ((h % n) + n) % n;
    f = ((f % n) + n) % n;
    p = ((p % n) + n) % n;
  }
  const d = F1(u, f, t),
    v = F1(h, f, t),
    g = F1(u, p, t),
    x = F1(h, p, t);
  return d + (v - d) * l + (g - d) * c + (d - v - g + x) * l * c;
}

/** Saltline fs — fbm over Ab; t = seed, n = octaves, s = wrap period (doubles per octave). */
function fs(i: number, e: number, t: number, n = 4, s = 0): number {
  let o = 0,
    r = 0.5,
    a = 0;
  for (let l = 0; l < n; l++) {
    o += r * Ab(i, e, t + l * 17, s);
    a += r;
    i *= 2;
    e *= 2;
    s *= 2;
    r *= 0.5;
  }
  return o / a;
}

/** Saltline Oy — 256² RGBA white noise from a fixed-seed xorshift. */
function makeTNoise(): THREE.DataTexture {
  const e = new Uint8Array(SIZE * SIZE * 4);
  let t = 2654435769;
  const n = (): number => {
    t ^= t << 13;
    t >>>= 0;
    t ^= t >>> 17;
    t ^= t << 5;
    t >>>= 0;
    return t / 4294967296;
  };
  for (let o = 0; o < SIZE * SIZE; o++) {
    e[o * 4] = n() * 256;
    e[o * 4 + 1] = n() * 256;
    e[o * 4 + 2] = n() * 256;
    e[o * 4 + 3] = 255;
  }
  const s = new THREE.DataTexture(e, SIZE, SIZE);
  s.wrapS = s.wrapT = THREE.RepeatWrapping;
  s.magFilter = s.minFilter = THREE.LinearFilter;
  s.generateMipmaps = false;
  s.colorSpace = THREE.NoColorSpace;
  s.needsUpdate = true;
  return s;
}

/** Saltline Cb — builds {det, nrm} byte tiles; det drives foam/gust, nrm drives wave normals. */
function buildDetailArrays(i: number): { det: Uint8Array; nrm: Uint8Array } {
  const e = new Uint8Array(i * i * 4);
  const t = new Uint8Array(i * i * 4);
  const n = new Float32Array(i * i);
  const s = new Float32Array(i * i);
  for (let r = 0; r < i; r++) {
    for (let a = 0; a < i; a++) {
      const l = a / i,
        c = r / i,
        u = r * i + a;
      const h = fs(l * 96, c * 96, 3, 2, 96) * 0.6 + fs(l * 40, c * 40, 9, 2, 40) * 0.4;
      const f = fs(l * 6, c * 6, 21, 4, 6);
      const p = (fs(l * 8, c * 8, 31, 2, 8) - 0.5) * 0.25;
      const d = (fs(l * 8, c * 8, 37, 2, 8) - 0.5) * 0.25;
      const v = 1 - Math.abs(2 * fs((l + p) * 5, (c + d) * 5, 43, 3, 5) - 1);
      const g = fs(l * 28, c * 28, 51, 3, 28);
      e[u * 4] = Math.round(sat(h) * 255);
      e[u * 4 + 1] = Math.round(sat(f) * 255);
      e[u * 4 + 2] = Math.round(sat(v) * 255);
      e[u * 4 + 3] = Math.round(sat(g) * 255);
      n[u] = h;
      s[u] = fs(l * 9, c * 9, 71, 4, 9);
    }
  }
  const o = (r: number): number => ((r % i) + i) % i;
  for (let r = 0; r < i; r++) {
    for (let a = 0; a < i; a++) {
      const l = r * i + a;
      const c = (n[r * i + o(a + 1)] - n[r * i + o(a - 1)]) * 2.2;
      const u = (n[o(r + 1) * i + a] - n[o(r - 1) * i + a]) * 2.2;
      const h = (s[r * i + o(a + 2)] - s[r * i + o(a - 2)]) * 9;
      const f = (s[o(r + 2) * i + a] - s[o(r - 2) * i + a]) * 9;
      t[l * 4] = Math.round(sat(0.5 - c) * 255);
      t[l * 4 + 1] = Math.round(sat(0.5 - u) * 255);
      t[l * 4 + 2] = Math.round(sat(0.5 - h) * 255);
      t[l * 4 + 3] = Math.round(sat(0.5 - f) * 255);
    }
  }
  return { det: e, nrm: t };
}

/** Saltline N1 — DataTexture wrapper: repeat-wrap, mipmapped, linear, raw values. */
function dataTex(data: Uint8Array, size: number): THREE.DataTexture {
  const s = new THREE.DataTexture(data, size, size);
  s.wrapS = s.wrapT = THREE.RepeatWrapping;
  s.magFilter = THREE.LinearFilter;
  s.minFilter = THREE.LinearMipmapLinearFilter;
  s.generateMipmaps = true;
  s.anisotropy = 4;
  s.colorSpace = THREE.NoColorSpace;
  s.needsUpdate = true;
  return s;
}

export interface NoiseTextures {
  /** 256² RGBA white noise — the sky shader's `tNoise`. */
  tNoise: THREE.DataTexture;
  /** 256² fbm pack (r=height, g=lowfreq, b=ridged, a=mid) — the sea's `uDetail`. */
  detail: THREE.DataTexture;
  /** 256² slope pack (.rg / .ba gradient pairs) — the sea's `uDetailN`. */
  detailN: THREE.DataTexture;
}

let cache: NoiseTextures | null = null;

/** Generated once, shared by sky + sea — ART-SPEC: no per-frame texture work. */
export function getNoiseTextures(): NoiseTextures {
  if (cache) return cache;
  const { det, nrm } = buildDetailArrays(SIZE);
  cache = {
    tNoise: makeTNoise(),
    detail: dataTex(det, SIZE),
    detailN: dataTex(nrm, SIZE),
  };
  return cache;
}
